inputs.manifest:
{
  "schema_version": "1.0.0",
  "id": "ideogram/inpaint",
  "label": {
    "en": "Inpaint",
    "ru": "Inpaint"
  },
  "family": "ideogram",
  "family_label": "Ideogram 4",
  "tier": 0,
  "mode": "inpaint",
  "order": 30,
  "controls": [
    {
      "param": "prompt",
      "kind": "prompt",
      "superprompt": true
    },
    {
      "param": "design_json",
      "kind": "designer",
      "provider": "ideogram",
      "label": {
        "en": "Layout",
        "ru": "Макет"
      }
    },
    {
      "param": "preset",
      "kind": "choice",
      "default": "Turbo",
      "label": {
        "en": "Preset",
        "ru": "Пресет"
      },
      "options": [
        {
          "value": "Quality",
          "label": {
            "en": "Quality",
            "ru": "Качество"
          },
          "tooltip": {
            "en": "48 steps — the most refined typography and detail, and the slowest.",
            "ru": "48 шагов — самая чистая типографика и детали, и самый долгий рендер."
          },
          "values": {
            "steps": 48,
            "mu": 0.0,
            "std": 1.5
          }
        },
        {
          "value": "Default",
          "label": {
            "en": "Normal",
            "ru": "Обычный"
          },
          "tooltip": {
            "en": "20 steps — the balanced setting.",
            "ru": "20 шагов — сбалансированный режим."
          },
          "values": {
            "steps": 20,
            "mu": 0.0,
            "std": 1.75
          }
        },
        {
          "value": "Turbo",
          "label": {
            "en": "Turbo",
            "ru": "Турбо"
          },
          "tooltip": {
            "en": "12 steps — quick drafts.",
            "ru": "12 шагов — быстрые наброски."
          },
          "values": {
            "steps": 12,
            "mu": 0.5,
            "std": 1.75
          }
        }
      ]
    },
    {
      "param": "seed",
      "kind": "seed"
    },
    {
      "param": "denoise",
      "kind": "strength",
      "default": 0.3,
      "stops": [
        0.1,
        0.2,
        0.3,
        0.45,
        1.0
      ],
      "replace_at": 0.6,
      "replace_label": {
        "en": "Replace",
        "ru": "Замена"
      },
      "label": {
        "en": "Repaint strength",
        "ru": "Сила перерисовки"
      },
      "tooltip": {
        "en": "How much of the masked area is redrawn. Up to 45% the model reworks the pixels that are there — skin, texture, small fixes. Replace regenerates the area from scratch at full strength.",
        "ru": "Насколько сильно перерисовывается область под маской. До 45% модель дорабатывает то, что есть, — кожу, фактуру, мелкие правки. Замена рисует область заново, на полную силу."
      }
    },
    {
      "param": "megapixels",
      "kind": "slider",
      "min": 0.5,
      "max": 4.0,
      "step": 0.1,
      "default": 0.8,
      "label": {
        "en": "Processing resolution",
        "ru": "Разрешение обработки"
      },
      "tooltip": {
        "en": "Megapixels the masked crop is redrawn at. A small selection is upscaled toward this budget (more detail, slower); an oversized one is scaled down to it.",
        "ru": "В скольких мегапикселях перерисовывается вырезанный по маске фрагмент. Маленькое выделение увеличивается до этого бюджета (больше деталей, дольше), слишком большое — уменьшается."
      }
    },
    {
      "param": "loras",
      "kind": "loras",
      "max": 8,
      "strength": [
        -2.0,
        2.0
      ]
    },
    {
      "param": "think_steps",
      "kind": "number",
      "advanced": true,
      "min": 1,
      "max": 12,
      "label": {
        "en": "Think steps (quality)",
        "ru": "Шаги размышления (качество)"
      },
      "default": 2,
      "tooltip": {
        "en": "How many times the sampler re-checks the repaint against its surroundings on every step. Each turn is another pass through the model, so this is the main quality-versus-time knob: 2 is enough for an ordinary repaint, 5+ for a hard one.",
        "ru": "Сколько раз на каждом шаге сэмплер сверяет перерисовку с окружением. Каждый заход — это ещё один проход через модель, поэтому здесь и решается «качество против времени»: 2 хватает обычной правке, 5 и больше — сложной."
      }
    },
    {
      "param": "steps",
      "kind": "number",
      "advanced": true,
      "min": 1,
      "max": 60,
      "label": {
        "en": "Steps",
        "ru": "Шаги"
      },
      "default": 12
    },
    {
      "param": "cfg",
      "kind": "number",
      "advanced": true,
      "min": 0,
      "max": 15,
      "step": 0.1,
      "label": {
        "en": "CFG",
        "ru": "CFG"
      }
    }
  ],
  "refs": {
    "max": 0
  },
  "requires": [
    "source_image",
    "mask"
  ],
  "negative_prompt": false,
  "models": [
    {
      "title": "studio:model",
      "input": "unet_name",
      "folder": "diffusion_models",
      "match": "ideogram4_(fp8|int8)(?!.*uncond)"
    },
    {
      "title": "studio:model_uncond",
      "input": "unet_name",
      "folder": "diffusion_models",
      "match": "ideogram4_unconditional"
    },
    {
      "title": "studio:clip",
      "input": "clip_name",
      "folder": "text_encoders",
      "match": "qwen3vl_8b"
    },
    {
      "title": "studio:vae",
      "input": "vae_name",
      "folder": "vae",
      "match": "flux2.*flux2-vae-v2"
    }
  ],
  "dependencies": [
    {
      "pack": "LanPaint",
      "nodes": [
        "LanPaint_SamplerCustomAdvanced",
        "LanPaint_MaskBlend"
      ]
    }
  ],
  "designer": {
    "param": "design_json",
    "mode_param": "mode",
    "caption_param": "auto_caption",
    "preset": "Ideogram Prompt Enhance"
  },
  "literals": {
    "mode": {
      "node": "designer",
      "input": "mode"
    }
  },
  "prompt_source": {
    "node": "designer",
    "slot": 0
  },
  "_note_context": "Умолчание контекста 60 при потолке 100 — шире, чем у остальных семейств (25/50). Ideogram 4 обучен КОМПОНОВАТЬ кадр, а не продолжать чужой: чем меньше вокруг маски видимой сцены, тем увереннее он рисует внутри выреза самостоятельную композицию в своём масштабе. Подсказка у контрола общая для всех семейств намеренно — одни и те же слова у одного и того же ползунка; причина отличия живёт здесь и в project_memory/reference_ideogram_inpaint.md."
}
